def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        # Visit each diagonal from its boundary start.
        starts = []
        for r in range(h):
            for c in range(w):
                pr, pc = r - dr, c - dc
                if not (0 <= pr < h and 0 <= pc < w):
                    starts.append((r, c))

        for r0, c0 in starts:
            line = []
            r, c = r0, c0
            while 0 <= r < h and 0 <= c < w:
                line.append((r, c))
                r += dr
                c += dc

            i = 0
            while i < len(line):
                r, c = line[i]
                color = grid[r][c]
                if color == 7:
                    i += 1
                    continue

                j = i + 1
                while j < len(line) and grid[line[j][0]][line[j][1]] == color:
                    j += 1

                # Extend a same-color diagonal segment of at least two cells
                # only at ends that are not adjacent to another colored segment.
                if j - i >= 2:
                    for idx, step in ((i, -1), (j - 1, 1)):
                        neighbor = idx + step
                        if 0 <= neighbor < len(line):
                            nr, nc = line[neighbor]
                            if grid[nr][nc] != 7:
                                continue

                        rr, cc = line[idx]
                        rr += step * dr
                        cc += step * dc
                        while 0 <= rr < h and 0 <= cc < w:
                            if out[rr][cc] == 7:
                                out[rr][cc] = color
                            rr += step * dr
                            cc += step * dc

                i = j

    return out
